name: Set Pay attention label for ignored issues
on:
  schedule:
    - cron: '0 10 * * 1-5'

jobs:
  set-label-for-issues:
    runs-on: ubuntu-latest
    steps:
      - name: Set Pay attention label for ignored issues
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.DEVTOOLS_GITHUB_TOKEN }}
          script: |
            const issuesList = await github.rest.issues.listForRepo({
              owner: context.repo.owner,
              repo: context.repo.repo,
            })
            if (issuesList.data && issuesList.status === 200) {
              for (const issue of issuesList.data) {
                const createdDaysDelta = (new Date() - new Date(issue.created_at)) / (1000 * 60 * 60 * 24);

                if (!issue.labels.length && (
                  (!issue.pull_request && createdDaysDelta > 2) || (issue.pull_request && createdDaysDelta > 7)
                )) {
                  await github.rest.issues.addLabels({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    issue_number: issue.number,
                    labels: ['pay attention']
                  });
                }
              }
            }

export { fetchAuthData } from './fetchAuthData';
export { fetchTunnelData } from './fetchTunnelData';
export { fetchUserData } from './fetchUserData';

import querystring from 'node:querystring';
import { API_HOST } from '../constants';
import { axiosWithRetry } from './axiosWithRetry';

interface VkApiError {
  error: {
    error_code: number;
    error_msg: string;
  };
}

interface FetchTunnelDataResponse {
  response: {
    tunnel_url: string;
    token: string;
    host: string;
    url: string;
  };
}

interface FetchTunnelDataRequest {
  access_token: string;
  version: number;
  v: string;
  app_id?: number;
  staging?: boolean;
  endpoints?: string[];
}

export async function fetchTunnelData({
  access_token,
  version,
  v,
  app_id,
  staging,
  endpoints,
}: FetchTunnelDataRequest) {
  const params: Record<string, string | number | boolean> = {
    access_token,
    version,
    v,
  };

  if (app_id) params['app_id'] = app_id;
  if (staging) params['staging'] = staging;
  if (endpoints) params['endpoints'] = endpoints.join(',');

  const tunnelData = await axiosWithRetry({
    url: `${API_HOST}apps.getTunnelToken?${querystring.stringify(params)}`,
    options: {},
    onError: (error) => console.error('An error occurred when requesting tunnel settings:', error),
  });

  return tunnelData.data as FetchTunnelDataResponse | VkApiError;
}

import { isAxiosError } from 'axios';
import { OAUTH_HOST, TUNNEL_APP_ID } from '../constants';
import { VkAuthError } from '../types';
import { axiosWithRetry } from './axiosWithRetry';

interface FetchAccessTokenResponse {
  user_id: number;
  access_token: string;
}

interface FetchAccessTokenRequest {
  deviceId: string;
}

export async function fetchUserData({ deviceId }: FetchAccessTokenRequest) {
  const userData = await axiosWithRetry({
    url: `${OAUTH_HOST}code_auth_token?device_id=${deviceId}&client_id=${TUNNEL_APP_ID}`,
    options: {},
    onError: (error) => {
      console.error('An error occurred when requesting user data');
      if (error && typeof error === 'object' && isAxiosError(error)) {
        console.error('Reason:', error.response?.data?.error_description);
      } else {
        console.error(error);
      }
    },
  });

  return userData.data as FetchAccessTokenResponse | VkAuthError;
}

import { TunnelClient } from '@/entities/TunnelClient';
import { RawData, WebSocket } from 'ws';
import { parseHttpRequest } from '@/helpers';
import { HttpProtocol, WsProtocol, UserProxyAppSettings } from '@/types';

vi.mock('@/helpers', () => ({ parseHttpRequest: vi.fn() }));

describe('TunnelClient (pure computation methods)', () => {
  let client: TunnelClient;
  const socket = {} as WebSocket;
  const tunnelData = {
    tunnelHost: 'tunnel.vk.com',
    tunnelUrl: 'https://tunnel.vk.com/connect',
    tunnelToken: '[REDACTED]',
    url: 'https://localhost:3000',
    userId: 123456,
  };

  const userSettings = {
    host: 'myhost',
    wsProtocol: WsProtocol.WS,
    httpProtocol: HttpProtocol.HTTP,
    insecure: 0,
    wsOrigin: 1,
    port: 1234,
    timeout: 5000,
  } as UserProxyAppSettings;

  beforeEach(() => {
    client = new TunnelClient(socket, tunnelData, userSettings);
  });

  it('parseProxyRequest разбивает RawData корректно', () => {
    const rawData = Buffer.from('00000001HGET /test HTTP/1.1\n\n');
    (parseHttpRequest as any).mockReturnValue({ headers: {}, uri: '/test', method: 'GET' });

    const result = (client as any).parseProxyRequest(rawData as RawData);

    expect(result.seq).toBe('00000001');
    expect(result.messageType).toBe('H');
    expect(result.payload.toString()).toContain('GET /test');
    expect(result.endpoint).toBe('/test');
  });

  it('transformPayload заменяет Host и Accept-Encoding', () => {
    const rawPayload = Buffer.from('GET / HTTP/1.1\nHost: example.com\nAccept-Encoding: gzip\n\n');
    const transformed = (client as any).transformPayload(rawPayload);

    expect(transformed).toContain('Host: myhost');
    expect(transformed).toContain('Accept-Encoding: gzip;q=0,deflate;q=0');
  });
});

import { parseHttpRequest } from '@/helpers/parseHttpRequest';

describe('parseHttpRequest', () => {
  it('Сохраняет повторяющиеся заголовки в массив', () => {
    const rawRequest = [
      'GET / HTTP/1.1',
      'Host: example.com',
      'Cookie: a=1',
      'Cookie: b=2',
      'User-Agent: test',
      '',
      'body content',
    ].join('\n');

    const result = parseHttpRequest(rawRequest);

    expect(result.headers['Cookie']).toEqual(['a=1', 'b=2']);
    expect(result.headers['Host']).toBe('example.com');
    expect(result.headers['User-Agent']).toBe('test');
  });

  it('Не модифицирует body запроса', () => {
    const bodyContent = ['line1', 'line2', 'line3'].join('\r\n');
    const rawRequest = [
      'POST /submit HTTP/1.1',
      'Host: example.com',
      'Content-Type: text/plain',
      '',
      bodyContent,
    ].join('\n');

    const result = parseHttpRequest(rawRequest);

    expect(result.body).toBe(bodyContent);
  });

  it('Корректно обрабатывает websocket upgrade', () => {
    const rawRequest = [
      'GET /ws HTTP/1.1',
      'Host: example.com',
      'Upgrade: websocket',
      'Connection: Upgrade',
      '',
      '',
    ].join('\n');

    const result = parseHttpRequest(rawRequest);

    expect(result.method).toBe('GET');
    expect(result.uri).toBe('/ws');
    expect(result.headers['Upgrade']).toBe('websocket');
    expect(result.headers['Connection']).toBe('Upgrade');
  });

  it('поддерживает разные разделители CRLF и LF', () => {
    const rawRequestCRLF = 'GET / CRLF/1.1\r\nHost: test\r\n\r\nbody';
    const rawRequestLF = 'GET / LF/1.1\nHost: test\n\nbody';

    const resultCRLF = parseHttpRequest(rawRequestCRLF);
    const resultLF = parseHttpRequest(rawRequestLF);

    expect(resultCRLF.body).toBe('body');
    expect(resultLF.body).toBe('body');
  });
});

import http from 'http';
import { vkTunnel } from '@/vkTunnel';
import axios from 'axios';
import { ensureAuth } from './utils/ensureAuth';

describe.sequential('Интеграционный тест HTTP через туннель', () => {
  let server: http.Server;
  let port: number;

  let tunnelData: Awaited<ReturnType<typeof vkTunnel>>['tunnelData'];
  let closeTunnelConnection: () => void;

  beforeAll(async () => {
    ensureAuth();

    server = http.createServer((req, res) => {
      if (req.url === '/' && req.method === 'GET') {
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ result: true }));
      } else if (req.url === '/echo' && req.method === 'POST') {
        let body = '';
        req.on('data', (chunk) => (body += chunk));
        req.on('end', () => {
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(body);
        });
      } else if (req.url?.startsWith('/cookie')) {
        res.writeHead(200, { 'Set-Cookie': 'session=12345' });
        res.end('ok');
      } else if (req.url?.startsWith('/query')) {
        const url = new URL(req.url, `http://localhost:${port}`);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ query: url.searchParams.get('name') }));
      } else if (req.url?.startsWith('/error')) {
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'internal' }));
      } else {
        res.writeHead(404);
        res.end();
      }
    });

    await new Promise<void>((resolve) => server.listen(0, resolve));
    const address = server.address();
    if (typeof address !== 'object' || !address?.port) {
      throw new Error('Failed to get server port');
    }

    port = address.port;
    vi.stubEnv('PROXY_PORT', port.toString());

    const tunnel = await vkTunnel();
    tunnelData = tunnel.tunnelData;
    closeTunnelConnection = tunnel.closeTunnelConnection;
  });

  afterAll(async () => {
    server.close();
    closeTunnelConnection();
  });

  afterEach(() => {
    vi.unstubAllEnvs();
  });

  it('GET / базовый сценарий', async () => {
    const res = await axios.get(`${tunnelData.tunnelUrl}/`);

    expect(res.status).toBe(200);
    expect(res.data).toEqual({ result: true });
  });

  it('POST /echo передача JSON', async () => {
    const payload = { foo: 'bar' };
    const res = await axios.post(`${tunnelData.tunnelUrl}/echo`, payload);

    expect(res.status).toBe(200);
    expect(res.data).toEqual(payload);
  });

  it('GET /cookie проброс заголовков Set-Cookie', async () => {
    const res = await axios.get(`${tunnelData.tunnelUrl}/cookie`);

    expect(res.status).toBe(200);
    expect(res.headers['set-cookie']).toContain('session=12345');
  });

  it('GET /query?name=test проброс query-параметров', async () => {
    const res = await axios.get(`${tunnelData.tunnelUrl}/query?name=test`);

    expect(res.status).toBe(200);
    expect(res.data).toEqual({ query: 'test' });
  });

  it('GET /error проброс ошибки', async () => {
    try {
      await axios.get(`${tunnelData.tunnelUrl}/error`);
      throw new Error('Ожидалась ошибка');
    } catch (err: any) {
      expect(err.response.status).toBe(500);
      expect(err.response.data).toEqual({ error: 'internal' });
    }
  });
});

import { HttpProxy } from '@/entities/HttpProxy';
import {
  UserProxyAppSettings,
  ProxiedNetworkPacket,
  HttpProtocol,
  WsProtocol,
  MessageTypeFromBack,
} from '@/types';

export const USER_SETTINGS: UserProxyAppSettings = {
  httpProtocol: HttpProtocol.HTTP,
  wsProtocol: WsProtocol.WS,
  timeout: 5000,
  host: 'localhost',
  port: 3000,
  insecure: 0,
  wsOrigin: 0,
};

export const PACKET_DATA: ProxiedNetworkPacket = {
  seq: '00000001',
  messageType: MessageTypeFromBack.HTTP,
  endpoint: '/test',
  isWebsocketUpgrade: false,
  payload: Buffer.from('GET /test HTTP/1.1\r\nHost: localhost\r\n\r\n'),
  parsedRequest: {
    method: 'GET',
    uri: '/test',
    headers: { Host: 'localhost' },
    body: '',
  },
};

describe('HttpProxy (unit)', () => {
  let httpProxy: HttpProxy;
  const sendResponseMock = vi.fn();

  beforeEach(() => {
    httpProxy = new HttpProxy(USER_SETTINGS);

    vi.restoreAllMocks();
  });

  it('Должен получить ответ от локального сервера, распарсить его и отправить на бекенд туннеля', async () => {
    const fakeResponse = {
      status: 200,
      statusText: 'OK',
      headers: { 'Content-Type': 'text/plain' },
      data: Buffer.from('Hello World'),
    };

    (httpProxy as any).getResponseFromProxiedServer = vi.fn(() => Promise.resolve(fakeResponse));

    await httpProxy.proxy(PACKET_DATA, sendResponseMock);

    expect(sendResponseMock).toHaveBeenCalledTimes(1);

    const sentBuffer = sendResponseMock.mock.calls[0][0] as Buffer;
    const bufferText = sentBuffer.toString();

    expect(bufferText).toContain('HTTP/1.1 200 OK');
    expect(bufferText).toContain('Content-Type: text/plain');
    expect(bufferText).toContain('Hello World');
  });

  it('Должен получить ответ от локального сервера, распарсить его и отправить на бекенд туннеля, сохранив все заголовки', async () => {
    const fakeResponse = {
      status: 200,
      statusText: 'OK',
      headers: { 'Set-Cookie': ['a=1', 'b=2'] },
      data: Buffer.from('data'),
    };

    (httpProxy as any).getResponseFromProxiedServer = vi.fn(() => Promise.resolve(fakeResponse));

    await httpProxy.proxy(PACKET_DATA, sendResponseMock);

    const sentBuffer = sendResponseMock.mock.calls[0][0] as Buffer;
    const bufferText = sentBuffer.toString();
    expect(bufferText).toContain('Set-Cookie: a=1');
    expect(bufferText).toContain('Set-Cookie: b=2');
  });

  it('Не отправляет ответ на бек туннеля, если локальный сервер не отвечает', async () => {
    (httpProxy as any).getResponseFromProxiedServer = vi.fn(() => Promise.resolve(undefined));

    await httpProxy.proxy(PACKET_DATA, sendResponseMock);

    expect(sendResponseMock).not.toHaveBeenCalled();
  });
});

import { WsProxy } from '@/entities/WsProxy';
import {
  UserProxyAppSettings,
  ProxiedNetworkPacket,
  HttpProtocol,
  WsProtocol,
  MessageTypeFromBack,
} from '@/types';
import WebSocket from 'ws';

describe('WsProxy (unit)', () => {
  const VALID_SEQ = 'SEQ123';
  const TEST_ENDPOINT = '/chat';
  const TEST_HEADERS = {
    'Sec-WebSocket-Protocol': 'json',
    'Sec-WebSocket-Extensions': 'permessage-deflate',
    'Sec-WebSocket-Key': 'abc123',
    'Sec-WebSocket-Version': '13',
    'X-Custom-Header': 'SHOULD_BE_FILTERED',
  };
  const MOCK_USER_SETTINGS: UserProxyAppSettings = {
    httpProtocol: HttpProtocol.HTTP,
    wsProtocol: WsProtocol.WS,
    host: 'localhost',
    port: 8080,
    timeout: 5000,
    insecure: 0,
    wsOrigin: 1,
    app_id: undefined,
    staging: undefined,
    endpoints: undefined,
  };

  let wsProxy: WsProxy;

  const mockSend = vi.fn((data: any, options: any, callback?: (err?: Error) => void) => {
    if (callback) callback();
  });
  const mockClose = vi.fn();

  beforeEach(() => {
    wsProxy = new WsProxy(MOCK_USER_SETTINGS);
    vi.clearAllMocks();
  });

  it('filterWebSocketHeaders должен возвращать только разрешённые заголовки', () => {
    const filtered = (wsProxy as any).filterWebSocketHeaders(TEST_HEADERS);

    expect(filtered).toEqual({
      'Sec-WebSocket-Protocol': 'json',
      'Sec-WebSocket-Extensions': 'permessage-deflate',
      'Sec-WebSocket-Key': 'abc123',
      'Sec-WebSocket-Version': '13',
    });
    expect(filtered).not.toHaveProperty('X-Custom-Header');
  });

  it('closeConnection должен закрывать сохранённое соединение', () => {
    const fakeWs = { send: mockSend, close: mockClose } as unknown as WebSocket;
    (wsProxy as any).connections.set(VALID_SEQ, fakeWs);

    (wsProxy as any).closeConnection(VALID_SEQ);

    expect(mockClose).toHaveBeenCalledTimes(1);
  });

  it('proxy должен закрывать соединение при messageType=WEBSOCKET_CLOSE', async () => {
    const fakeWs = { send: mockSend, close: mockClose } as unknown as WebSocket;
    (wsProxy as any).connections.set(VALID_SEQ, fakeWs);

    const packet: ProxiedNetworkPacket = {
      seq: VALID_SEQ,
      endpoint: TEST_ENDPOINT,
      payload: Buffer.from(''),
      messageType: MessageTypeFromBack.WEBSOCKET_CLOSE,
      isWebsocketUpgrade: false,
      parsedRequest: { method: 'GET', uri: TEST_ENDPOINT, headers: {}, body: '' },
    };

    await wsProxy.proxy(packet, vi.fn());

    expect(mockClose).toHaveBeenCalledTimes(1);
  });
});

import http from 'http';
import WebSocket, { WebSocketServer } from 'ws';
import { vkTunnel } from '@/vkTunnel';
import { ensureAuth } from './utils/ensureAuth';

describe.sequential('Интеграционный тест WebSocket через туннель', () => {
  let server: http.Server;
  let wss: WebSocketServer;
  let port: number;

  let tunnelData: Awaited<ReturnType<typeof vkTunnel>>['tunnelData'];
  let closeTunnelConnection: () => void;

  beforeAll(async () => {
    ensureAuth();

    server = http.createServer();
    wss = new WebSocketServer({ server });

    wss.on('connection', (ws) => {
      ws.on('message', (msg, isBinary) => {
        ws.send(msg, { binary: isBinary });
      });
    });

    await new Promise<void>((resolve) => server.listen(0, resolve));

    const address = server.address();

    if (typeof address !== 'object' || !address?.port) {
      throw new Error('Failed to get server port');
    }

    port = address.port;
    vi.stubEnv('PROXY_PORT', port.toString());

    const tunnel = await vkTunnel();
    tunnelData = tunnel.tunnelData;
    closeTunnelConnection = tunnel.closeTunnelConnection;
  });

  afterAll(async () => {
    wss.close();
    server.close();
    closeTunnelConnection();
    vi.unstubAllEnvs();
  });

  it('Устанавливается соединение и работает echo', async () => {
    const wsUrl = tunnelData.tunnelUrl.replace('https', 'wss');
    const ws = new WebSocket(wsUrl);

    await new Promise<void>((resolve, reject) => {
      ws.on('open', () => {
        ws.send('hello through tunnel');
      });

      ws.on('message', (data) => {
        expect(data.toString()).toBe('hello through tunnel');
        ws.close();
        resolve();
      });

      ws.on('error', reject);
    });
  });

  it('Поддерживается бинарный формат', async () => {
    const wsUrl = tunnelData.tunnelUrl.replace('https', 'wss');
    const ws = new WebSocket(wsUrl);

    const payload = Buffer.from([1, 2, 3, 4]);

    await new Promise<void>((resolve, reject) => {
      ws.on('open', () => {
        ws.send(payload);
      });

      ws.on('message', (data, isBinary) => {
        expect(isBinary).toBe(true);
        expect(Buffer.compare(data as Buffer, payload)).toBe(0);
        ws.close();
        resolve();
      });

      ws.on('error', reject);
    });
  });
});

